function FeatureWorkspace({slug,title}){
 const profile=workspaceProfiles[slug]||{kind:'general',label:catalog[slug]?.[1]||'IKAI ONE WORKSPACE',title:title+' workspace',subtitle:catalog[slug]?.[2]||'Explore this workflow using illustrative operational records.',metrics:[['Workflow steps','03'],['Sample records','03'],['Live connection','Not connected'],['Mode','Demo']],rows:(catalog[slug]?.[4]||['Review requirements','Organise information','Plan next steps']).map((item,i)=>['0'+(i+1),item,'Sample workflow','Review and confirm','Planned'])}
 const [search,setSearch]=useState('')
 const [notice,setNotice]=useState('')
 const [pincode,setPincode]=useState('54000')
 const [activeTab,setActiveTab]=useState('All')
 const [checked,setChecked]=useState([])
 const [expanded,setExpanded]=useState(-1)
 const [enquiryOpen,setEnquiryOpen]=useState(false)
 const rows=profile?.rows||[]
 const visibleRows=rows.filter(row=>{const text=row.join(' ').toLowerCase();if(!text.includes(search.toLowerCase()))return false;if(activeTab==='Needs review')return /review|pending|exception|to do|draft|awaiting|reschedule|not connected/i.test(text);if(activeTab==='In progress')return /transit|progress|active|ready|connected|delivered|matched|confirmed/i.test(text);return true})
 const isFaq=profile?.kind==='faq'
 const faqs=[['Are these live courier rates?','No. Any sample rates or operational figures on this prototype are illustrative and are not a live quote.'],['Can I book a courier from this page?','Not yet. Live booking requires a backend service and an authorised courier integration.'],['Can I track a real parcel here?','This prototype can demonstrate a tracking workflow, but real tracking events require a carrier or tracking API connection.'],['Is COD settlement connected?','No. COD balances and reconciliation states are sample records until settlement data is integrated.'],['How do I get started?','Use the Get started action to explore the current signup flow, or contact the IKAI One team about your workflow.']]
 if(!profile)return null
 return <section className="feature-workspace">
  <div className="feature-workspace-head"><div><span className="domestic-overline">{profile.label}</span><h2>{profile.title}</h2><p>{profile.subtitle}</p></div><span className="domestic-demo-badge"><i/> DEMO WORKSPACE</span></div>
  <div className="feature-metrics">{profile.metrics.map(([label,value])=><article key={label}><small>{label}</small><b>{value}</b></article>)}</div>
  {profile.kind==='coverage'&&<div className="feature-inline-tool"><label>Destination postcode<input value={pincode} onChange={e=>setPincode(e.target.value)} inputMode="numeric" maxLength={5} placeholder="e.g. 54000"/></label><button className="domestic-btn domestic-btn-primary" onClick={()=>setNotice(['75500','54000','44000','38000','60000','25000'].includes(pincode)?'Sample coverage found for '+pincode+'. This is not a live courier serviceability check.':'No sample match for that postcode. Live coverage requires a courier lookup.')}>Check sample coverage <ArrowRight size={15}/></button></div>}
  {profile.kind==='developer'&&<div className="feature-code-panel"><div><span>EXAMPLE REQUEST · SANDBOX CONCEPT</span><button onClick={()=>setNotice('API example selected. Connect a backend and issue secure credentials before using real requests.')}>Review integration steps <ArrowUpRight size={14}/></button></div><pre>{'POST /v1/shipments\nContent-Type: application/json\nAuthorization: Bearer <YOUR_TEST_TOKEN>\n\n{\n  "origin": "Lahore",\n  "destination": "Karachi",\n  "weightKg": 1.2,\n  "paymentMethod": "COD",\n  "codAmountPkr": 2500\n}'}</pre><small>No credentials or live API are configured in this frontend demo.</small></div>}
  {profile.kind==='faq'&&<div className="feature-faq-list">{faqs.map(([q,a],i)=><article key={q}><button aria-expanded={expanded===i} onClick={()=>setExpanded(expanded===i?-1:i)}>{q}<ChevronDown size={16}/></button>{expanded===i&&<p>{a}</p>}</article>)}</div>}
  {profile.kind==='knowledge'&&<div className="feature-knowledge-grid">{rows.map((r,i)=><article key={r[0]}><span>0{i+1}</span><div><b>{r[1]}</b><p>{r[2]} · {r[3]}</p></div><button onClick={()=>setNotice(r[1]+' opened in demo preview.')}>Open <ArrowRight size={13}/></button></article>)}</div>}
  {profile.kind!=='faq'&&profile.kind!=='knowledge'&&<><div className="feature-workspace-tools"><div className="domestic-tabs">{['All','Needs review','In progress'].map(t=><button key={t} className={activeTab===t?'active':''} onClick={()=>setActiveTab(t)}>{t}</button>)}</div><label className="domestic-search"><Search size={15}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder={'Search '+title.toLowerCase()}/></label></div><div className="domestic-table-wrap"><table className="domestic-table"><thead><tr><th>{profile.kind==='developer'?'Method':profile.kind==='locations'?'ID':'Reference'}</th><th>{profile.kind==='cod'?'Order / record':profile.kind==='integrations'?'Workflow':profile.kind==='developer'?'Endpoint':'Name / details'}</th><th>Context</th><th>Next step</th><th>Status</th></tr></thead><tbody>{visibleRows.map((row,i)=><tr key={row[0]}>{row.map((cell,j)=><td key={j}>{j===0?<b className="domestic-shipment-id">{cell}</b>:cell}</td>)}<td><button className="domestic-row-more" aria-label={'Open '+row[0]} onClick={()=>setNotice(row[0]+': this is a sample record. Connect the relevant integration to perform a live action.')}><ArrowUpRight size={14}/></button></td></tr>)}{visibleRows.length===0&&<tr><td colSpan="6" className="domestic-empty">No matching sample records.</td></tr>}</tbody></table></div></>}
  {['enquiry','growth'].includes(profile.kind)&&<div className="feature-next-step"><div><b>{profile.kind==='enquiry'?'Discuss this workflow':'Plan your workflow'}</b><p>Save a local demo enquiry to outline the requirements. No information is sent to a server.</p></div><button className="domestic-btn domestic-btn-primary" onClick={()=>setEnquiryOpen(!enquiryOpen)}>{enquiryOpen?'Close form':'Start an enquiry'} <ArrowRight size={15}/></button>{enquiryOpen&&<ContactForm onDone={()=>{setEnquiryOpen(false);setNotice('Demo enquiry complete. No backend submission occurred.')}}/>}</div>}
  {notice&&<div className="feature-workspace-notice" role="status"><CircleCheck size={16}/><span>{notice}</span><button onClick={()=>setNotice('')} aria-label="Dismiss"><X size={15}/></button></div>}
  <div className="feature-workspace-disclaimer"><ShieldCheck size={15}/> Sample workflow and records only. Live courier booking, rates, tracking, financial services, messaging and APIs require authorised integrations and backend services.</div>
 </section>
}

function FeaturePage({slug}) {
 const [title,eyebrow,description,audience,bullets]=catalog[slug]||[titleFromSlug(slug),'IKAI ONE','Explore a connected way to organise ecommerce shipping and delivery workflows.','For businesses that want a clearer view of shipping operations.',['Organise the workflow','Keep shipment details visible','Review progress and next steps']]
 const [showContact,setShowContact]=useState(false)
 const [origin,setOrigin]=useState('Lahore'),[destination,setDestination]=useState('Karachi'),[weight,setWeight]=useState('1'),[length,setLength]=useState('20'),[width,setWidth]=useState('15'),[height,setHeight]=useState('10')
 const isTool=slug?.includes('calculator')
 const volumetric=slug==='volumetric-weight-calculator'
 const dimensional=(Math.max(0,Number(length))*Math.max(0,Number(width))*Math.max(0,Number(height)))/5000
 const estimate=Math.round(150+Math.max(0,Number(weight)-0.5)*45+(origin===destination?0:35))
 return <><PublicHeader/><main className="public-page"><div className="public-breadcrumb"><Link to="/">Home</Link><ChevronRight size={13}/><span>{title}</span></div><section className="public-hero"><div className="public-hero-copy"><span className="public-eyebrow"><i/>{eyebrow}</span><h1>{title}<br/><em>{slug==='shipping-rate-calculator'?'with clarity':slug==='volumetric-weight-calculator'?'before you ship':'made simpler'}.</em></h1><p>{description}</p><div className="public-hero-actions"><Link className="public-primary" to="/signup">Get started <ArrowRight size={16}/></Link><button className="public-secondary" onClick={()=>setShowContact(true)}>Talk to our team <ArrowUpRight size={15}/></button></div><div className="public-trust-row"><span><ShieldCheck size={15}/> Clear operational workflows</span><span><BadgeCheck size={15}/> Built for growing teams</span></div></div><div className="public-hero-visual"><div className="public-visual-top"><span><Boxes size={16}/> IKAI WORKSPACE</span><i>ILLUSTRATIVE</i></div><div className="public-visual-title"><div><small>WORKFLOW OVERVIEW</small><h2>{title}</h2></div><span className="public-visual-mark"><Sparkles size={20}/></span></div><div className="public-visual-stats"><div><span>Visibility</span><b>One view</b><small>Less switching</small></div><div><span>Workflow</span><b>Connected</b><small>Clear next steps</small></div></div><div className="public-visual-list">{bullets.map((item,i)=><div key={item}><span>{i+1}</span><div><b>{item}</b><small>{['Organised information','Clear hand-offs','Actionable visibility'][i]}</small></div><Check size={15}/></div>)}</div><div className="public-visual-bottom"><span><i/> Demo concept</span><span>IKAI One · {title}</span></div></div></section>
 {isTool&&<section className="public-tool-panel"><div className="public-section-heading"><span>INTERACTIVE TOOL</span><h2>{volumetric?'Volumetric weight calculator':'Shipping rate estimator'}</h2><p>Illustrative calculations only. Final pricing and divisors depend on the selected courier.</p></div><div className="public-tool-grid">{volumetric?<><label>Length (cm)<input type="number" min="0" value={length} onChange={e=>setLength(e.target.value)}/></label><label>Width (cm)<input type="number" min="0" value={width} onChange={e=>setWidth(e.target.value)}/></label><label>Height (cm)<input type="number" min="0" value={height} onChange={e=>setHeight(e.target.value)}/></label></>:<><label>Origin city<select value={origin} onChange={e=>setOrigin(e.target.value)}>{['Lahore','Karachi','Islamabad','Faisalabad','Multan','Peshawar'].map(v=><option key={v}>{v}</option>)}</select></label><label>Destination city<select value={destination} onChange={e=>setDestination(e.target.value)}>{['Karachi','Lahore','Islamabad','Faisalabad','Multan','Peshawar'].map(v=><option key={v}>{v}</option>)}</select></label><label>Actual weight (kg)<input type="number" min="0.1" step="0.1" value={weight} onChange={e=>setWeight(e.target.value)}/></label></>}<div className="public-tool-result"><span>{volumetric?'Dimensional weight':'Illustrative estimate'}</span><b>{volumetric?dimensional.toFixed(2)+' kg':'Rs '+estimate.toLocaleString('en-PK')}</b><small>{volumetric?'Using a sample divisor of 5,000':'Not a live courier quote'}</small></div></div></section>}
 <FeatureWorkspace slug={slug} title={title}/>\n <section className="public-benefits"><div className="public-section-heading"><span>BUILT AROUND THE WORK</span><h2>A clearer way to move forward.</h2><p>{audience}</p></div><div className="public-benefit-grid">{bullets.map((item,i)=>{const Icon=[PackageCheck,Truck,BarChart3][i];return <article key={item}><span className="public-benefit-icon"><Icon size={19}/></span><small>0{i+1} / CAPABILITY</small><h3>{item}</h3><p>{['Keep information organised so your team can work from the same context.','Make hand-offs and next steps easier to understand.','Review progress with a consistent view of the workflow.'][i]}</p></article>})}</div></section>
 <section className="public-cta-band"><div><span>READY WHEN YOU ARE</span><h2>Bring your shipping workflow together.</h2><p>Explore the IKAI One workspace or talk through the workflow that fits your business.</p></div><div><Link className="public-primary" to="/signup">Get started <ArrowRight size={16}/></Link><button className="public-secondary" onClick={()=>setShowContact(true)}>Contact the team <Mail size={15}/></button></div></section></main><PublicFooter/>
 {showContact&&<div className="public-contact-overlay" onMouseDown={e=>{if(e.target===e.currentTarget)setShowContact(false)}}><section className="public-contact-modal"><button className="public-contact-close" onClick={()=>setShowContact(false)}>Close ×</button><span className="public-eyebrow"><i/> TALK TO IKAI</span><h2>Tell us about your workflow.</h2><p>Leave your details in this demo enquiry form. Nothing is sent to a backend.</p><ContactForm onDone={()=>setShowContact(false)}/></section></div>}
 </>
}
function ContactForm({onDone}){const [name,setName]=useState(''),[email,setEmail]=useState(''),[company,setCompany]=useState(''),[need,setNeed]=useState('Multi-courier shipping');const [saved,setSaved]=useState(false);return <form className="public-contact-form" onSubmit={e=>{e.preventDefault();setSaved(true);setTimeout(onDone,1200)}}><label>Your name<input required value={name} onChange={e=>setName(e.target.value)} placeholder="Full name"/></label><label>Work email<input type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@company.com"/></label><label>Company<input required value={company} onChange={e=>setCompany(e.target.value)} placeholder="Company name"/></label><label>What are you exploring?<select value={need} onChange={e=>setNeed(e.target.value)}>{['Multi-courier shipping','Cross-border shipping','COD & reconciliation','Returns & NDR','Channel integration','Partnership'].map(v=><option key={v}>{v}</option>)}</select></label><button className="public-primary" type="submit">{saved?'Enquiry saved in demo':'Submit enquiry'} <ArrowRight size={15}/></button></form>}
function PricingPage(){const [volume,setVolume]=useState('500–2,000');return <><PublicHeader/><main className="public-page"><section className="public-pricing-hero"><span className="public-eyebrow"><i/> TRANSPARENT PLANNING</span><h1>Pricing that fits<br/><em>your shipping flow.</em></h1><p>Tell us roughly how much you ship to explore a suitable starting point. Final rates depend on courier availability, service, destination and package details.</p><div className="public-pricing-control"><label>Monthly shipment volume<select value={volume} onChange={e=>setVolume(e.target.value)}>{['Under 500','500–2,000','2,000–10,000','10,000+'].map(v=><option key={v}>{v}</option>)}</select></label><div><small>Recommended next step</small><b>{volume==='Under 500'?'Start with the core workflow':volume==='500–2,000'?'Compare services and COD workflows':volume==='2,000–10,000'?'Discuss operational requirements':'Plan an enterprise workflow'}</b></div><Link className="public-primary" to="/signup">Get started <ArrowRight size={15}/></Link></div><div className="public-pricing-grid">{[['Starter','For growing sellers','Order organisation, shipment tracking and core workflows'],['Growth','For multi-courier teams','Courier comparison, COD visibility and reporting'],['Scale','For high-volume operations','Workflow planning, integration requirements and team visibility']].map(([name,forWho,desc],i)=><article key={name} className={i===1?'recommended':''}><span>{i===1?'POPULAR WORKFLOW':'IKAI ONE'}</span><h2>{name}</h2><p>{forWho}</p><div className="public-plan-note">Custom quote <small>No public rates are being represented as confirmed pricing.</small></div><ul>{desc.split(', ').map(item=><li key={item}><Check size={14}/>{item}</li>)}</ul><Link to="/signup">Explore this plan <ArrowRight size={14}/></Link></article>)}</div></section></main><PublicFooter/></>}
function TrackingPage(){const [awb,setAwb]=useState('IK-248601'),[searched,setSearched]=useState(false);return <><PublicHeader/><main className="public-page public-tracking-page"><section className="public-tracking-hero"><span className="public-eyebrow"><i/> SHIPMENT VISIBILITY</span><h1>Track an order.<br/><em>Find the next update.</em></h1><p>Enter an IKAI demo reference or tracking number to view sample shipment progress.</p><form onSubmit={e=>{e.preventDefault();setSearched(true)}}><Search size={18}/><input value={awb} onChange={e=>setAwb(e.target.value)} placeholder="Enter order or tracking ID"/><button className="public-primary">Track shipment <ArrowRight size={15}/></button></form><small>Demo tracking only. Courier live APIs are not connected.</small></section>{searched&&<section className="public-tracking-result"><div className="public-track-result-head"><span><PackageCheck size={18}/> TRACKING RESULT</span><b>{awb||'IK-248601'}</b></div><h2>In transit <span>Illustrative status</span></h2><p>Your sample shipment is moving through the delivery network.</p><div className="public-tracking-steps">{[['Booked','Shipment information received'],['Picked up','Parcel handed to courier'],['In transit','Moving through the network'],['Out for delivery','With the local delivery team'],['Delivered','Delivered to recipient']].map(([a,b],i)=><div key={a} className={i<3?'complete':''}><span>{i<3?<Check size={13}/>:i+1}</span><div><b>{a}</b><small>{b}</small></div></div>)}</div></section>}</main><PublicFooter/></>}
function InvestorsPage(){return <><PublicHeader/><main className="public-page"><section className="public-pricing-hero"><span className="public-eyebrow"><i/> INVESTOR RELATIONS</span><h1>Building clearer<br/><em>commerce operations.</em></h1><p>IKAI One is developing a connected shipping and logistics workspace for ecommerce and business operations. For investor enquiries, share your contact details through our demo enquiry form.</p><Link className="public-primary" to="/signup">Get in touch <ArrowRight size={16}/></Link><div className="public-benefit-grid public-investor-grid">{[['Mission','Make shipping operations easier to understand and manage.'],['Platform','Connect orders, courier workflows, tracking and COD visibility.'],['Approach','Build practical workflows with clear operational context.']].map(([title,desc])=><article key={title}><span className="public-benefit-icon"><Globe2 size={19}/></span><h3>{title}</h3><p>{desc}</p></article>)}</div></section></main><PublicFooter/></>}
export default function PublicPages(){const {slug}=useParams();const path=window.location.pathname;const page=useMemo(()=>path==='/pricing'?'pricing':path==='/track-order'?'tracking':path==='/investors'?'investors':slug||'all-features',[path,slug]);if(page==='pricing')return <PricingPage/>;if(page==='tracking')return <TrackingPage/>;if(page==='investors')return <InvestorsPage/>;if(page==='domestic-shipping')return <DomesticShippingPage/>;return <FeaturePage slug={page}/>}
